11:  * normalized reason. This extension neither changes the card class nor adds the value to any
12:  * other incident vocabulary. Unknown reasons and malformed fields remain incompatible.</p>
13:  */
14: public final class EventIncidentsV17Parser extends EventIncidentsV16Parser {
15: 
16:     public static final String PARSER_VERSION = "event-incidents-v17";
17: 
18:     private final Set<String> supportedCardReasons = withProfessionalHandball(super.cardReasons());
19: 
20:     @Override
21:     protected String parserVersion() {
22:         return PARSER_VERSION;
23:     }
24: 
25:     @Override
26:     protected Set<String> cardReasons() {
27:         return supportedCardReasons;
28:     }
29: 
30:     private static Set<String> withProfessionalHandball(Set<String> historicalReasons) {
31:         Set<String> reasons = new HashSet<>(historicalReasons);
32:         reasons.add("Professional handball");
