16: 
17: /** Adds optional officials and the named round to the unchanged V3 sporting contract. */
18: public final class EventDetailsV4Parser {
19:     public static final String PARSER_VERSION = "event-details-v4";
20:     private static final Set<String> RECOGNIZED = Set.of("$.event.homeTeam.manager", "$.event.awayTeam.manager",
21:             "$.event.referee", "$.event.roundInfo.name");
22:     private final EventDetailsV3Parser baseParser = new EventDetailsV3Parser();
23:     private static final JsonMapper JSON = JsonMapper.builder()
24:             .enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION)
25:             .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
26: 
27:     public EventDetailsParseResult parse(long snapshotId, RawPayloadEvidence payload, Instant receivedAt) {
28:         JsonNode event = null;
29:         try {
30:             JsonNode root = JSON.readTree(payload.bytes());
31:             if (root != null && root.isObject()) event = root.get("event");
32:         } catch (JacksonException ignored) {
33:             // The unchanged base parser reports strict JSON failures against the original bytes.
34:         }
35:         Optional<String> preferredRound = event != null && event.isObject()
36:                 ? ProviderPeopleParserSupport.text(event.path("roundInfo").get("name"), "$.event.roundInfo.name", 64, ignored -> { })
37:                 : Optional.empty();
38:         var base = baseParser.parseWithPreferredRound(snapshotId, payload, receivedAt, preferredRound);
39:         var original = base.evidence();
40:         var evidence = new EventDetailsParseEvidence(original.sourceReference(), original.rawSha256(),
41:                 original.canonicalJsonSha256(), original.recordedAt(), PARSER_VERSION);
42:         var warnings = new ArrayList<>(base.warnings().stream().filter(w -> !RECOGNIZED.contains(w.path())).toList());
43:         if (base.status() != EventDetailsParseStatus.PARSED)
44:             return EventDetailsParseResult.failed(base.status(), evidence, warnings, base.problems());
45:         Consumer<String> invalid = path -> {
46:             if (warnings.size() < 128) warnings.add(new EventDetailsParseWarning(
47:                     EventDetailsParseWarning.Code.OPTIONAL_FIELD_INVALID, path, "Invalid optional metadata ignored by event-details-v4"));
48:         };
49:         var home = ProviderPeopleParserSupport.person(event.path("homeTeam").get("manager"), "$.event.homeTeam.manager", invalid);
50:         var away = ProviderPeopleParserSupport.person(event.path("awayTeam").get("manager"), "$.event.awayTeam.manager", invalid);
51:         var referee = ProviderPeopleParserSupport.person(event.get("referee"), "$.event.referee", invalid);
52:         var roundName = ProviderPeopleParserSupport.text(event.path("roundInfo").get("name"), "$.event.roundInfo.name", 64, invalid);
53:         var d = base.details().orElseThrow();
54:         return EventDetailsParseResult.parsed(evidence, new EventDetails(d.providerEventId(), d.startsAt(), d.homeTeam(),
55:                 d.awayTeam(), d.status(), d.tournament(), d.venue(), d.season(), roundName.isPresent() ? roundName : d.round(),
56:                 d.isAwarded(), d.homeDisplayScore(), d.awayDisplayScore(), home, away, referee), warnings);
57:     }
58: }
