12: /** Player country enrichment; V3 statistics retain absent, empty and zero separately. */
13: public final class EventLineupsV4Parser {
14:     public static final String PARSER_VERSION = "event-lineups-v4";
15:     private final EventLineupsV3Parser baseParser = new EventLineupsV3Parser();
16: 
17:     public J5ParseResult<EventLineups> parse(long snapshotId, long expectedEventId, RawPayloadEvidence payload, Instant receivedAt) {
18:         var base = baseParser.parse(snapshotId, expectedEventId, payload, receivedAt);
19:         var e = base.evidence();
20:         var evidence = new J5ParseEvidence(e.sourceReference(), e.endpointType(), e.rawSha256(), e.canonicalJsonSha256(), e.recordedAt(), PARSER_VERSION);
21:         if (base.status() != J5ParseStatus.PARSED)
22:             return J5ParseResult.failed(base.status(), evidence, base.warnings(), base.problems());
23:         var root = JsonMapper.builder().build().readTree(payload.bytes());
24:         var d = base.data().orElseThrow();
25:         var warnings = new ArrayList<>(base.warnings());
26:         return J5ParseResult.parsed(evidence, new EventLineups(expectedEventId, d.confirmed(),
27:                 team(d.home(), root.path("home"), "$.home", warnings),
28:                 team(d.away(), root.path("away"), "$.away", warnings)),
29:                 base.completeness().orElseThrow(), warnings);
30:     }
31: 
32:     private static TeamLineup team(TeamLineup team, JsonNode source, String path, List<J5ParseWarning> warnings) {
33:         var players = new ArrayList<EventLineupPlayer>();
34:         for (int i = 0; i < team.players().size(); i++) {
35:             var player = team.players().get(i);
36:             var country = ProviderPeopleParserSupport.country(source.path("players").get(i).path("player").get("country"), path + ".players[" + i + "].player.country", invalid -> {
37:                 if (warnings.size() < 128) warnings.add(new J5ParseWarning(J5ParseWarning.Code.OPTIONAL_FIELD_INVALID,
38:                         invalid, "Invalid optional country metadata ignored by event-lineups-v4"));
39:             });
40:             players.add(new EventLineupPlayer(player.providerPlayerId(), player.name(), player.shirtNumber(), player.position(),
41:                     player.starter(), player.captain(), player.statistics(), country));
42:         }
43:         var missing = team.missingPlayers().map(previous -> {
44:             var values = new ArrayList<MissingLineupPlayer>();
45:             for (int i = 0; i < previous.size(); i++) {
46:                 var player = previous.get(i);
47:                 var country = ProviderPeopleParserSupport.country(source.path("missingPlayers").get(i).path("player").get("country"),
48:                         path + ".missingPlayers[" + i + "].player.country", invalid -> {
49:                             if (warnings.size() < 128) warnings.add(new J5ParseWarning(J5ParseWarning.Code.OPTIONAL_FIELD_INVALID,
50:                                     invalid, "Invalid optional country metadata ignored by event-lineups-v4"));
51:                         });
52:                 values.add(new MissingLineupPlayer(player.providerPlayerId(), player.name(), player.shirtNumber(), player.position(),
53:                         player.type(), player.reason(), player.description(), player.externalType(), player.expectedEndDate(), country));
54:             }
55:             return List.copyOf(values);
56:         });
57:         return new TeamLineup(team.side(), team.formation(), players, missing);
58:     }
59: }

