231:     private static void compareLineupSide(
232:             List<J6SemanticChange> changes,
233:             TeamLineup before,
234:             TeamLineup after) {
235:         if (before.side() != after.side()) {
236:             throw new IllegalArgumentException("lineup sides must match");
237:         }
238:         String side = before.side().name();
239:         scalar(changes, "lineups[" + side + "].formation",
240:                 before.formation().orElse(null), after.formation().orElse(null));
241:         compareMissingPlayers(changes, side, before.missingPlayers(), after.missingPlayers());
242:         Map<Long, List<EventLineupPlayer>> beforeById = groupBy(
243:                 before.players(), EventLineupPlayer::providerPlayerId);
244:         Map<Long, List<EventLineupPlayer>> afterById = groupBy(
245:                 after.players(), EventLineupPlayer::providerPlayerId);
246:         Set<Long> ids = orderedUnion(beforeById.keySet(), afterById.keySet(), Long::compareTo);
247:         for (Long id : ids) {
248:             List<EventLineupPlayer> oldValues = mutable(beforeById.get(id));
249:             List<EventLineupPlayer> newValues = mutable(afterById.get(id));
250:             removeExactMatches(oldValues, newValues);
251:             String path = "lineups[" + side + ",playerId=" + id + "]";
252:             if (oldValues.size() == 1 && newValues.size() == 1) {
253:                 EventLineupPlayer oldValue = oldValues.getFirst();
254:                 EventLineupPlayer newValue = newValues.getFirst();
255:                 scalar(changes, path + ".name", oldValue.name(), newValue.name());
256:                 scalar(changes, path + ".number",
257:                         oldValue.shirtNumber().orElse(null),
258:                         newValue.shirtNumber().orElse(null));
259:                 scalar(changes, path + ".position",
260:                         oldValue.position().orElse(null), newValue.position().orElse(null));
261:                 scalar(changes, path + ".starter", oldValue.starter(), newValue.starter());
262:                 scalar(changes, path + ".captain",
263:                         oldValue.captain().orElse(null), newValue.captain().orElse(null));
264:                 compareCountry(changes, path + ".country",
265:                         oldValue.country(), newValue.country());
266:                 comparePlayerStatistics(changes, path + ".statistics",
267:                         oldValue.statistics(), newValue.statistics());
268:                 continue;
269:             }
270:             removeEntities(changes, path, oldValues, J6SemanticDiffService::lineupSummary);
271:             addEntities(changes, path, newValues, J6SemanticDiffService::lineupSummary);
272:         }
273:     }
