601:     private static <T> void removeExactMatches(List<T> before, List<T> after) {
602:         for (int beforeIndex = before.size() - 1; beforeIndex >= 0; beforeIndex--) {
603:             int afterIndex = after.indexOf(before.get(beforeIndex));
604:             if (afterIndex >= 0) {
605:                 before.remove(beforeIndex);
606:                 after.remove(afterIndex);
607:             }
608:         }
609:     }
