611:     private static <T> void removeEntities(
612:             List<J6SemanticChange> changes,
613:             String basePath,
614:             List<T> values,
615:             Function<T, String> summary) {
616:         for (int index = 0; index < values.size(); index++) {
617:             String path = values.size() == 1 ? basePath : basePath + "#" + (index + 1);
618:             changes.add(new J6SemanticChange(
619:                     path,
620:                     Optional.of(summary.apply(values.get(index))),
621:                     Optional.empty(),
622:                     J6ChangeKind.REMOVED));
623:         }
624:     }
625: 
626:     private static <T> void addEntities(
627:             List<J6SemanticChange> changes,
628:             String basePath,
629:             List<T> values,
630:             Function<T, String> summary) {
631:         for (int index = 0; index < values.size(); index++) {
632:             String path = values.size() == 1 ? basePath : basePath + "#" + (index + 1);
633:             changes.add(new J6SemanticChange(
634:                     path,
635:                     Optional.empty(),
636:                     Optional.of(summary.apply(values.get(index))),
637:                     J6ChangeKind.ADDED));
638:         }
639:     }
