641:     private static <T> Set<T> orderedUnion(
642:             Set<T> before,
643:             Set<T> after,
644:             Comparator<T> comparator) {
645:         return java.util.stream.Stream.concat(before.stream(), after.stream())
646:                 .distinct()
647:                 .sorted(comparator)
648:                 .collect(Collectors.toCollection(LinkedHashSet::new));
649:     }
