651:     private static void scalar(
652:             List<J6SemanticChange> changes,
653:             String field,
654:             Object before,
655:             Object after) {
656:         Optional<String> oldValue = stringValue(before);
657:         Optional<String> newValue = stringValue(after);
658:         if (oldValue.equals(newValue)) {
659:             return;
660:         }
661:         J6ChangeKind kind = oldValue.isEmpty()
662:                 ? J6ChangeKind.ADDED
663:                 : newValue.isEmpty() ? J6ChangeKind.REMOVED : J6ChangeKind.CHANGED;
664:         changes.add(new J6SemanticChange(field, oldValue, newValue, kind));
665:     }
