481:     private static void pairExactIncidents(
482:             List<PositionedIncident> before,
483:             List<PositionedIncident> after) {
484:         for (int beforeIndex = before.size() - 1; beforeIndex >= 0; beforeIndex--) {
485:             PositionedIncident candidate = before.get(beforeIndex);
486:             int match = -1;
487:             for (int afterIndex = 0; afterIndex < after.size(); afterIndex++) {
488:                 if (candidate.incident().equals(after.get(afterIndex).incident())) {
489:                     match = afterIndex;
490:                     break;
491:                 }
492:             }
493:             if (match >= 0) {
494:                 before.remove(beforeIndex);
495:                 after.remove(match);
496:             }
497:         }
498:     }
499: 
500:     private static void pairUnique(
501:             List<PositionedIncident> before,
502:             List<PositionedIncident> after,
503:             Function<PositionedIncident, String> keyFunction,
504:             List<IncidentPair> pairs) {
505:         Map<String, List<PositionedIncident>> beforeByKey = incidentGroups(
506:                 before,
507:                 keyFunction);
508:         Map<String, List<PositionedIncident>> afterByKey = incidentGroups(
509:                 after,
510:                 keyFunction);
511:         Set<PositionedIncident> matchedBefore = new LinkedHashSet<>();
512:         Set<PositionedIncident> matchedAfter = new LinkedHashSet<>();
513:         for (Map.Entry<String, List<PositionedIncident>> entry : beforeByKey.entrySet()) {
514:             List<PositionedIncident> candidatesAfter = afterByKey.get(entry.getKey());
515:             if (entry.getValue().size() == 1
516:                     && candidatesAfter != null
517:                     && candidatesAfter.size() == 1) {
518:                 PositionedIncident oldValue = entry.getValue().getFirst();
519:                 PositionedIncident newValue = candidatesAfter.getFirst();
520:                 pairs.add(new IncidentPair(oldValue, newValue));
521:                 matchedBefore.add(oldValue);
522:                 matchedAfter.add(newValue);
523:             }
524:         }
525:         before.removeAll(matchedBefore);
526:         after.removeAll(matchedAfter);
527:     }
528: 
529:     private static Map<String, List<PositionedIncident>> incidentGroups(
530:             List<PositionedIncident> values,
531:             Function<PositionedIncident, String> keyFunction) {
532:         Map<String, List<PositionedIncident>> result = new LinkedHashMap<>();
533:         for (PositionedIncident value : values) {
534:             String key = keyFunction.apply(value);
535:             if (key != null) {
536:                 result.computeIfAbsent(key, ignored -> new ArrayList<>()).add(value);
537:             }
